class Solution {
public:
    long long maximumOr(std::vector<int>& nums, int k) {
        int n = nums.size();
        std::vector<long long> prefix(n + 1, 0), suffix(n + 1, 0);
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] | nums[i];
        for (int i = n - 1; i >= 0; i--) suffix[i] = suffix[i + 1] | nums[i];
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            ans = std::max(ans, prefix[i] | ((long long)nums[i] << k) | suffix[i + 1]);
        }
        return ans;
    }
};

class Solution {
    public long maximumOr(int[] nums, int k) {
        int n = nums.length;
        long[] prefix = new long[n + 1];
        long[] suffix = new long[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] | nums[i];
        for (int i = n - 1; i >= 0; i--) suffix[i] = suffix[i + 1] | nums[i];
        long ans = 0;
        for (int i = 0; i < n; i++) {
            ans = Math.max(ans, prefix[i] | ((long)nums[i] << k) | suffix[i + 1]);
